Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>

using namespace std;

typedef pair<int,int> par;

const int MAXR = 11;
const int MAXN = 1000;
const int MAXM = 100100;
const int oo = (1<<29);

struct Edge {
    int to, nxt, cap, flow;
};

Edge edges[2*MAXM];
int last[MAXN], now[MAXN], lev[MAXN], cola[MAXN];
int E, n, s, t, enq, deq;

void init_maxflow( int nn, int ss, int tt ){
    n = nn; s = ss; t = tt; E = 0;
    memset(last, -1, sizeof(last));
}
void add_edge( int u, int v, int c ){
    edges[E] = {v, last[u], c, 0};
    last[u] = E++;
    edges[E] = {u, last[v], 0, 0};
    last[v] = E++;
}
bool bfs(){
    memset(lev, 0, sizeof(lev));
    enq = deq = 0;
    cola[enq++] = s;
    lev[s] = 1;
    while( deq < enq && !lev[t] ){
        int u = cola[deq++];
        for( int e = last[u]; e != -1; e = edges[e].nxt ){
            int v = edges[e].to;
            if( !lev[v] && edges[e].flow < edges[e].cap ){
                lev[v] = lev[u] + 1;
                cola[enq++] = v;
            }
        }
    }
    return lev[t];
}
int dfs( int u, int F ){
    if( u == t ) return F;
    for( int &e = now[u]; e != -1; e = edges[e].nxt ){
        int v = edges[e].to;
        if( lev[u] < lev[v] && edges[e].flow < edges[e].cap ){
            int f = dfs( v , min( F , edges[e].cap - edges[e].flow ) );
            if( f ){
                edges[e].flow += f;
                edges[e^1].flow -= f;
                return f;
            }
        }
    }
    return 0;
}
int max_flow(){
    int F = 0;
    while( bfs() ){
        memcpy(now, last, sizeof(last));
        int f;
        while( (f = dfs( s , oo )) ) F += f;
    }
    return F;
}

int R;
string m1[MAXR];
string m2[MAXR];

int movI[] = { 0 , 1 , 0 , -1 };
int movJ[] = { 1 , 0 , -1 , 0 };

bool can_move( int i, int j ){
    return ( i >= 0 && j >= 0 && i < R && j < R && m1[i][j] != 'Y' && m1[i][j] != 'Z' );
}

int tim[2][MAXR][MAXR];

void bfs2( int i, int j, int cc ){
    for( int k = 0; k < R; k++ ){
        for( int l = 0; l < R; l++ ){
            tim[cc][k][l] = 0;
        }
    }

    tim[cc][i][j] = 1;
    queue<par> q;
    q.push( make_pair( i , j ) );
    while( !q.empty() ){
        int ci = q.front().first;
        int cj = q.front().second;
        q.pop();

        if( cc == 1 && (tim[0][ci][cj] && tim[0][ci][cj] <= tim[1][ci][cj]) ){
            continue;
        }

        for( int k = 0; k < 4; k++ ){
            int ii = ci + movI[k];
            int jj = cj + movJ[k];

            if( can_move( ii , jj ) && !tim[cc][ii][jj] ){
                tim[cc][ii][jj] = tim[cc][ci][cj] + 1;
                q.push( make_pair( ii , jj ) );
            }
        }
    }
}

int nod[2][MAXR][MAXR];

int main(){
    ios::sync_with_stdio(0);
    cin.tie(0);

    int T; cin >> R >> T;

    int zi = 0, zj = 0;

    int n = 0, s = 0, t = 0;

    for( int i = 0; i < R; i++ ){
        cin >> m1[i];
        for( int j = 0; j < R; j++ ){
            if( m1[i][j] == 'Z' ){
                zi = i;
                zj = j;
            }
            else if( m1[i][j] != 'Y' ){
                n++;
                nod[0][i][j] = n;
            }
        }
    }

    for( int i = 0; i < R; i++ ){
        cin >> m2[i];
        for( int j = 0; j < R; j++ ){
            if( m2[i][j] != 'Y' && m2[i][j] != 'Z' ){
                n++;
                nod[1][i][j] = n;
            }
        }
    }

    n++;
    s = 0;
    t = n;

    init_maxflow( n , s , t );

    for( int i = 0; i < R; i++ ){
        for( int j = 0; j < R; j++ ){
            if( m1[i][j] != 'Z' && m1[i][j] != 'Y' ){
                add_edge( s , nod[0][i][j] , m1[i][j] - '0' );
                add_edge( nod[1][i][j] , t , m2[i][j] - '0' );
            }
        }
    }

    bfs2( zi , zj, 0 );

    for( int i = 0; i < R; i++ ){
        for( int j = 0; j < R; j++ ){
            if( m1[i][j] > '0' && m1[i][j] <= '9' ){
                bfs2( i , j , 1 );
                for( int ii = 0; ii < R; ii++ ){
                    for( int jj = 0; jj < R; jj++ ){
                        if( m2[ii][jj] > '0' && m2[ii][jj] <= '9' ){
                            if( tim[1][ii][jj] && (!tim[0][ii][jj] || tim[0][ii][jj] >= tim[1][ii][jj]) &&
                                tim[1][ii][jj]-1 <= T ){
                                add_edge( nod[0][i][j] , nod[1][ii][jj] , oo );
                            }
                        }
                    }
                }
            }
        }
    }

    cout << max_flow() << '\n';
}
